import './flow-i18n.js';
import {BUYERS,eligibleBuyers} from './transactions.js';
import {execute,connectWorkspace,synchronize,HOSTED_ENDPOINT} from './sync.js';
import {changeState,compressPhoto,readState} from './store.js';
import {newId,shortId} from './domain.js';
async function review(text){return new Promise(resolve=>{const dialog=document.createElement('dialog');const p=document.createElement('p');p.textContent=text;p.style.whiteSpace='pre-line';dialog.append(p);for(const [label,value]of [[ctx.t('close'),false],[ctx.t('acceptOffer'),true]]){const button=document.createElement('button');button.className='btn secondary';button.textContent=label;button.onclick=()=>{dialog.close();dialog.remove();resolve(value);};dialog.append(button);}dialog.addEventListener('cancel',()=>{dialog.remove();resolve(false);});document.body.append(dialog);dialog.showModal();});}
const fields=new Map();let ctx,working=false;
const values=id=>fields.get(id)||{};
export function safetyView(materialId,{t}){return `<div class="notice"><span aria-hidden="true">⚠</span><span><strong>${t('safety')}</strong><br>${t(materialId==='pcb'?'safetyPcb':materialId==='motors'?'safetyMotors':'safetyCables')} <a href="https://www.who.int/news-room/fact-sheets/detail/electronic-waste-(e-waste)" target="_blank" rel="noopener">WHO</a></span></div>`;}
export function flowView(state,lot,c){
  const {t,money,date,esc}=c,v=values(lot.id),offer=state.offers.find(o=>o.id===lot.acceptedOfferId),pickup=state.pickups.find(p=>p.lotId===lot.id),h=state.handovers.find(h=>h.lotId===lot.id&&h.status!=='superseded');
  const paid=state.payments.filter(p=>p.lotId===lot.id&&p.status==='confirmed').reduce((n,p)=>n+p.amountPaise,0);
  const action=(label,type,extra='')=>`<button class="btn secondary" data-tx="${type}" data-lot="${lot.id}" ${extra}>${t(label)}</button>`;
  const field=(name,label,type='text',value='')=>`<div class="field"><label for="flow-${name}">${t(label)}</label><input id="flow-${name}" data-flow-field="${name}" data-lot="${lot.id}" type="${type}" value="${esc(v[name]??value)}" ${['weight','amount'].includes(name)?'inputmode="decimal"':''}></div>`;
  let html=`<section class="card transaction-card"><h2>${t('saleFlow')}</h2><p class="small muted">${t('simulationNote')}</p>`;
  if(lot.status==='listed'){
    html+=`<h3>${t('offersTitle')}</h3>${state.offers.filter(o=>o.lotId===lot.id).slice().reverse().map(o=>`<div class="offer-row"><div><strong>${esc(BUYERS.find(b=>b.id===o.buyerId)?.name)}</strong><p>${money(o.ratePaise)}/kg · ${t(o.status)}</p><p class="small muted">${esc(o.note)}</p></div>${o.status==='pending'?action('acceptOffer','accept',`data-offer="${o.id}"`):''}</div>`).join('')}<details><summary>${t('eligible')}</summary>${eligibleBuyers(lot).map(b=>`<div class="offer-row"><div><strong>${esc(b.name)}</strong><p class="small muted">${t('demoBuyer')}<br>${t('pickupAvailable')}</p></div>${action('getOffer','offer',`data-buyer="${b.id}"`)}</div>`).join('')}</details>`;
  }
  if(offer)html+=`<div class="quote-summary"><strong>${esc(BUYERS.find(b=>b.id===offer.buyerId)?.name)}</strong><span>${t('agreedRate')}: ${money(offer.ratePaise)}/kg</span></div>`;
  if(offer&&['accepted','pickup'].includes(lot.status)&&(!pickup||pickup.status==='scheduled'))html+=`<h3>${t('schedulePickup')}</h3>${field('slot','pickupSlot','datetime-local')}${field('instructions','pickupInstructions','text',pickup?.instructions||'')}${action('savePickup','schedule')}`;
  if(pickup)html+=`<div class="quote-summary"><strong>${t('pickup')}: ${t(pickup.status)}</strong><span>${date(pickup.slot)}</span><span>${esc(pickup.instructions)}</span></div>${pickup.history.length?`<details><summary>${t('previousSlots')}</summary>${pickup.history.map(p=>`<p>${date(p.slot)} · ${esc(p.instructions)}</p>`).join('')}</details>`:''}`;
  if(pickup?.status==='arrived'&&(!h||h.status==='disputed'))html+=`<h3>${t('handoverTitle')}</h3>${h?.reason?`<p class="notice">${esc(h.reason)}</p>`:''}${field('weight','actualWeight','text',lot.weight)}${field('location','manualLocation','text',lot.locality)}<div class="field"><label for="handover-upload">${t('handoverPhoto')}</label><input id="handover-upload" data-lot="${lot.id}" type="file" accept="image/jpeg,image/png,image/webp"><button class="btn secondary" data-demo-photo="${lot.id}">${t('samplePhoto')}</button><span id="handover-photo-status">${v.photoId?t('photoReady'):''}</span></div>${safetyView(lot.materialId,c)}${action('submitHandover','handover')}`;
  if(h)html+=`<div class="quote-summary"><div class="lot-thumb" data-photo="${esc(h.photoId)}"></div><strong>${t('handoverTitle')}: ${t(h.status)}</strong><span>${h.grams/1000} kg × ${money(h.ratePaise)}/kg = ${money(h.finalValuePaise)}</span><span>${esc(h.location)} · ${date(h.submittedAt)}</span>${h.confirmedAt?`<a class="btn secondary" href="#receipt/${lot.id}">${t('receipt')}</a>`:''}</div>`;
  if(pickup&&['scheduled','on_way'].includes(pickup.status)||h?.status==='pending'||h?.confirmedAt&&paid<h.finalValuePaise){html+=`<details class="demo-actions"><summary>${t('demoActions')}</summary><p class="small muted">${t('simulationNote')}</p>`;
    if(pickup&&['scheduled','on_way'].includes(pickup.status))html+=action('advancePickup','advance');
    if(h?.status==='pending')html+=`${action('confirmHandover','confirm')}${field('reason','disputeReason')}${action('disputeHandover','dispute')}`;
    if(h?.confirmedAt&&paid<h.finalValuePaise)html+=`<p>${t('outstanding')}: <strong>${money(h.finalValuePaise-paid)}</strong></p>${field('amount','paymentAmount','text',((h.finalValuePaise-paid)/100).toFixed(2))}${action('recordPayment','payment')}`;
    html+='</details>';
  }
  return html+'</section>';
}
export function syncView(state,{t,esc,date}){const s=state.sync,v=values('sync');return `<section class="card transaction-card"><h2>${t('workspaceSync')}</h2><p>${t('syncHelp')}</p>${location.protocol==='https:'&&location.hostname!=='localhost'?'<p><a href="/signin-with-chatgpt?return_to=%2F" target="_top">Sign in with ChatGPT</a></p>':''}${s?.code?`<details><summary>${t('pairingCode')}</summary><code class="pairing-code">${esc(s.code)}</code></details><p class="small muted">${esc(s.endpoint)}</p><p>${s.lastSync?`${t('synced')}: ${date(s.lastSync)}`:t('waiting')}</p>${s.error?`<p class="notice">${esc(s.error)}</p>`:''}<button class="btn" data-sync="retry">${t('syncNow')}</button>`:`<div class="field"><label for="sync-endpoint">${t('serverAddress')}</label><input id="sync-endpoint" data-flow-field="endpoint" data-lot="sync" value="${esc(v.endpoint||(['localhost','127.0.0.1'].includes(location.hostname)&&location.protocol==='http:'?location.origin:HOSTED_ENDPOINT))}"></div><div class="field"><label for="sync-code">${t('pairingCode')}</label><input id="sync-code" data-flow-field="code" data-lot="sync" value="${esc(v.code||'')}" autocomplete="off" spellcheck="false"></div><div class="row"><button class="btn" data-sync="create">${t('createWorkspace')}</button><button class="btn secondary" data-sync="join">${t('joinWorkspace')}</button></div>`}<p class="small muted below">${t('connectionNote')}</p></section>`;}
export function notificationsView(state,{t,date,esc}){return `<h1>${t('notifications')}</h1><div class="card transaction-card">${state.events.length?state.events.slice().reverse().slice(0,100).map(e=>`<a class="notification-row" href="#lot/${e.lotId}"><strong>${esc(shortId(e.lotId))} · ${t(e.type)}</strong><span>${date(e.at)}</span></a>`).join(''):`<p>${t('noNotifications')}</p>`}</div>`;}
export function receiptView(state,id,{t,money,date,esc}){const lot=state.lots.find(l=>l.id===id),h=state.handovers.find(h=>h.lotId===id&&h.confirmedAt);if(!lot||!h)return `<p>${t('noHandover')}</p>`;const payments=state.payments.filter(p=>p.handoverId===h.id&&p.status==='confirmed'),paid=payments.reduce((n,p)=>n+p.amountPaise,0);return `<section class="card receipt transaction-card"><h1>${t('receiptTitle')}</h1><p>${esc(shortId(id))} · ${date(h.confirmedAt)}</p><p>${esc(BUYERS.find(b=>b.id===h.buyerId)?.name)} · ${t(lot.materialId)}</p><p>${h.grams/1000} kg × ${money(h.ratePaise)}/kg</p><div class="quote-summary"><strong>${t('saleValue')}: ${money(h.finalValuePaise)}</strong><span>${t('received')}: ${money(paid)}</span><span>${t('outstanding')}: ${money(h.finalValuePaise-paid)}</span></div><p>${esc(h.location)} (${t('manualLocation')})</p><table><thead><tr><th>${t('date')}</th><th>${t('received')}</th></tr></thead><tbody>${payments.map(p=>`<tr><td>${date(p.confirmedAt)}</td><td>${money(p.amountPaise)}</td></tr>`).join('')}</tbody></table><p class="small muted">${t('receiptNote')}</p><button class="btn no-print" data-print>${t('printReceipt')}</button></section>`;}
export function bindWorkflows(context){ctx=context;const app=document.querySelector('#app');
  app.addEventListener('input',event=>{const el=event.target;if(!el.dataset.flowField)return;const v={...values(el.dataset.lot),[el.dataset.flowField]:el.value};fields.set(el.dataset.lot,v);});
  app.addEventListener('change',async event=>{if(event.target.id!=='handover-upload')return;const el=event.target;try{const blob=await compressPhoto(el.files[0]);const id=newId('photo');await changeState(()=>{},{photo:{id,blob}});fields.set(el.dataset.lot,{...values(el.dataset.lot),photoId:id});document.querySelector('#handover-photo-status').textContent=ctx.t('photoReady');}catch(error){ctx.toast(error.message);}});
  app.addEventListener('click',async event=>{
    const samplePhoto=event.target.closest('[data-demo-photo]');if(samplePhoto){event.preventDefault();const canvas=document.createElement('canvas');canvas.width=640;canvas.height=400;const p=canvas.getContext('2d');p.fillStyle='#ecf5ed';p.fillRect(0,0,640,400);p.fillStyle='#227450';p.font='bold 30px sans-serif';p.fillText('SAMPLE HANDOVER PHOTO',80,210);const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));const id=newId('photo');await changeState(()=>{},{photo:{id,blob}});fields.set(samplePhoto.dataset.demoPhoto,{...values(samplePhoto.dataset.demoPhoto),photoId:id});document.querySelector('#handover-photo-status').textContent=ctx.t('samplePhoto');return;}
    const btn=event.target.closest('[data-tx],[data-sync],[data-print],[data-sample]');if(!btn)return;event.preventDefault();if(btn.hasAttribute('data-print'))return window.print();if(working)return;
    const state=await readState();const lot=state.lots.find(l=>l.id===btn.dataset.lot);
    if(btn.dataset.tx==='accept'){const offer=state.offers.find(o=>o.id===btn.dataset.offer);if(!await review(`${BUYERS.find(b=>b.id===offer.buyerId)?.name}\n${ctx.money(offer.ratePaise)}/kg · ≈ ${ctx.money(Math.round(offer.ratePaise*lot.estimatedGrams/1000))}\n${ctx.t('acceptReview')}`))return;}
    working=true;btn.disabled=true;
    try{
      if(ctx.isOffline())throw new Error(ctx.t('offline'));
      if(btn.dataset.sample){if(btn.dataset.sample==='reset'){if(!await review(ctx.t('resetSampleQuestion')))return;await execute({type:'reset_samples'});}else{const canvas=document.createElement('canvas');canvas.width=640;canvas.height=400;const pen=canvas.getContext('2d');pen.fillStyle='#e7f2e8';pen.fillRect(0,0,640,400);pen.fillStyle='#226348';pen.font='bold 40px sans-serif';pen.fillText('SAMPLE MATERIAL',90,185);pen.font='24px sans-serif';pen.fillText('Fictional demo photo',180,235);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));const id=newId('photo');await changeState(()=>{},{photo:{id,blob}});await execute({type:'sample',input:{photoId:id}});}}
      else if(btn.dataset.sync){if(btn.dataset.sync==='retry')await synchronize();else await connectWorkspace(document.querySelector('#sync-endpoint').value,document.querySelector('#sync-code').value,btn.dataset.sync==='create');}
      else{const input={...values(lot.id)};for(const el of app.querySelectorAll('[data-flow-field]'))if(el.dataset.lot===lot.id)input[el.dataset.flowField]=el.value;if(btn.dataset.offer)input.offerId=btn.dataset.offer;if(btn.dataset.buyer)input.buyerId=btn.dataset.buyer;if(input.slot)input.slot=new Date(input.slot).toISOString();await execute({type:btn.dataset.tx,lotId:lot.id,expectedVersion:lot.version,input});fields.delete(lot.id);}
      await ctx.reload();ctx.toast(ctx.t('updatedTransaction'));
    }catch(error){await ctx.reload();ctx.toast(error.message);}finally{working=false;btn.disabled=false;}
  });
}
